// Reduce the four probe responses into a single health snapshot.
// Each probe returns either a healthy status or an error string.
function probe(name, items) {
  const it = items.all[0];
  if (!it) return { service: name, healthy: false, status_code: null, latency_ms: null, error: 'no_response' };
  const j = it.json || {};
  const code = j.statusCode || j.status || null;
  const latency = j.headers?.['x-response-time'] ? parseInt(j.headers['x-response-time'], 10) : null;
  const healthy = code !== null && code >= 200 && code < 300;
  return {
    service: name,
    healthy,
    status_code: code,
    latency_ms: latency,
    error: healthy ? null : (j.body?.error || j.message || `http_${code}`)
  };
}

const probes = [
  probe('n8n', $items('Probe n8n')),
  probe('backend_api', $items('Probe Backend API')),
  probe('database', $items('Probe Database')),
  probe('redis', $items('Probe Redis'))
];

const unhealthy = probes.filter(p => !p.healthy);
const allHealthy = unhealthy.length === 0;

return {
  json: {
    checked_at: new Date().toISOString(),
    overall: allHealthy ? 'healthy' : 'unhealthy',
    probes,
    unhealthy_count: unhealthy.length,
    unhealthy_services: unhealthy.map(p => p.service)
  }
};

